const char *omni_country_name(const char *code)
{
    for (size_t i = 0; i < sizeof s_countries / sizeof s_countries[0]; i++)
        if (strcmp(s_countries[i].code, code) == 0) return s_countries[i].name;
    return code;
}

uint16_t omni_city_default(void)
{
    int i = omni_city_find_key(OMNI_DEFAULT_CITY_NAME, OMNI_DEFAULT_CITY_CC);
    return (uint16_t)(i < 0 ? 0 : i);
}
